sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.returnAsset = function(asset) {
    alert("Return flow will start for: " + asset.name);
  };

  c.renewAsset = function(asset) {
    alert("Renewal flow will start for: " + asset.name);
  };
};

sp_widget.css:
.active-assets {
  width: 86%;
  max-width: 1200px;
  margin: 0 auto 30px;

  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 10px;

  padding: 20px 25px;

  font-family: Arial, sans-serif;
}

.assets-header {
  display: flex;
  justify-content: space-between;
  align-items: center;

  padding-bottom: 15px;
  border-bottom: 1px solid #e5e7eb;
}

.assets-header h3 {
  margin: 0;
  color: #111827;
  font-size: 18px;
}

.asset-count {
  font-size: 12px;
  color: #2563eb;
  background: #eff6ff;
  padding: 5px 10px;
  border-radius: 20px;
}

.asset-row {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 18px 0;
  border-bottom: 1px solid #f0f0f0;
}

.asset-row:last-child {
  border-bottom: none;
}

.asset-info {
  display: flex;
  align-items: center;
  gap: 14px;
}

.asset-icon {
  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: #eff6ff;
  border-radius: 10px;

  font-size: 22px;
}

.asset-name {
  font-size: 15px;
  font-weight: 600;
  color: #111827;
}

.asset-due {
  font-size: 13px;
  color: #6b7280;
  margin-top: 4px;
}

.asset-actions {
  display: flex;
  gap: 10px;
}

.asset-actions button {
  padding: 8px 16px;

  border-radius: 6px;
  cursor: pointer;

  font-size: 13px;
  font-weight: 600;
}

.return-btn {
  background: #ffffff;
  color: #374151;
  border: 1px solid #d1d5db;
}

.renew-btn {
  background: #2563eb;
  color: #ffffff;
  border: 1px solid #2563eb;
}

/* Mobile */

@media (max-width: 768px) {

  .active-assets {
    width: 90%;
    padding: 18px;
  }

  .asset-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
  }

  .asset-actions {
    width: 100%;
  }

  .asset-actions button {
    flex: 1;
  }

}

